    tips: ["Base near Tam Coc or Trang An village to reach boats and the Hang Mua steps by bike.", "Take the Trang An boat route for the film-set cave-and-temple loop; Tam Coc for the rice-field classic.", "A room with a pool is a small luxury worth booking for hot afternoons."],
    scamWarnings: ["Agree the rowboat price and tipping expectation before setting off; touts oversell add-ons mid-river."],
    rating: 4.5, reviewSources: ["Booking.com", "Tripadvisor", "Google Maps consensus"],
