    hours: "Banh mi counters roughly 07:00-19:00; cao lau stalls at the Central Market strongest 10:00-17:00; famous shops sell out early",
    tips: ["Go before 11:00 to beat tour-group queues at the best-known banh mi counters", "Try cao lau at the Central Market food hall where several stalls compete side by side", "Point at the fillings you want - most counters have picture menus", "Eat cao lau in Hoi An itself; it is rarely authentic elsewhere"],
    scamWarnings: ["Confirm the price before ordering at market stalls; a few quote tourists double", "Ignore touts steering you to a 'better' shop nearby - they earn commission"],
    rating: 4.6, reviewSources: ["Tripadvisor", "Google Maps consensus"],
    mapQuery: "Hoi An Central Market street food", coords: { lat: 15.88, lng: 108.33 },
