    hours: "Roughly 06:00-11:00; the best shops sell out of broth by mid-morning, a few reopen in the evening",
    tips: ["Go between 06:30 and 08:30 when broth is freshest and turnover highest", "Say 'khong cay' for mild if you cannot handle the chili oil", "Add lime, herbs and banana blossom from the table basket like locals do", "A busy shop full of locals on small stools is the reliability signal"],
