    categories: ["food"], budgetTier: "low",
    isLocal: true,
    kidFriendly: true,
    blurb: "After dark, Vinh Khanh street in District 4 turns into Saigon's most famous seafood strip: pavement tables, tanks of live snails, clams, crab and prawns, and cooks grilling scallops with spring onion oil and peanuts. Loud, smoky and completely local - this is 'oc' (snail) culture at full volume, washed down with cold beer.",
    whyItFits: "The definitive Saigon night-eating experience, a short ride from District 1 but priced and paced for locals rather than tourists.",
    priceRange: { low: 100000, typical: 250000, high: 500000, currency: "VND", note: "Guidance per person: plates of snails or shellfish 50,000-150,000 VND each; premium items such as grilled crab claws 200,000-500,000 VND; a generous shared spread with drinks 200,000-500,000 VND per head." },
    hours: "Roughly 16:00 until late - many venues serve past midnight, some to 02:00; liveliest 18:00-22:00",
    tips: ["Order a few plates at a time - dishes arrive fast and portions add up", "Grilled scallops with scallion oil and salt-and-chili razor clams are the classics", "Pick a venue with visible live tanks and printed prices", "Go with a group so you can sample more dishes"],
    scamWarnings: ["Confirm whether pricing is per plate or per 100 grams before the seafood is weighed", "Check the bill line by line; extra side dishes and wet wipes are chargeable", "Keep an eye on bags - it is a busy open street"],
    rating: 4.3, reviewSources: ["Tripadvisor", "Google Maps consensus"],
    mapQuery: "Vinh Khanh seafood street District 4 Ho Chi Minh City", coords: { lat: 10.76, lng: 106.7 },
