    hours: "Night market roughly 17:00-22:00 daily; busiest on weekend evenings",
    tips: ["Watch it being grilled and eat it immediately - it loses crispness fast", "Pair it with a cup of hot soy milk (sua dau nanh), the classic Da Lat combo", "Weeknights are far less crowded than weekends", "Bring a light jacket - evenings drop to 15C or lower"],
    scamWarnings: ["Agree the price before topping additions are piled on", "Check 'Da Lat strawberries' bought at night stalls - some vendors sell cheaper imported fruit as local"],
    rating: 4.4, reviewSources: ["Tripadvisor", "Google Maps consensus"],
