    blurb: "Same nationwide ATM/SIM picture as elsewhere in Vietnam. Vinmec Can Tho gives the Mekong Delta's largest city an international-standard hospital option (029 2368 3003), making it the natural referral point for smaller Delta towns as well as the practical base for anyone touring the floating markets.",
    whyItFits: "The orientation card for the Mekong Delta's main hub - a genuine international-standard hospital exists here, useful to know if basing a Delta trip around this city.",
