    categories: ["culture", "food"], budgetTier: "low",
    blurb: "A working fishing village on Phu Quoc's east coast at the foot of the Ham Ninh mountains, and the island's main seafood supplier. A pier lined with seafood restaurants serves the local speciality, Ham Ninh crab.",
